components.css:
.ds-menu-item { display: flex; flex-direction: column; gap: 0; background: #20222e; color: #c0caf5; font: 400 1em/1 monospace; padding: 0 1ch; list-style: none; }
.ds-menu-item__marker { position: absolute; left: 0; color: #7aa2f7; }
.ds-menu-item__name { padding-left: 3ch; }
.ds-menu-item__desc { color: #565f89; padding-left: 3ch; }
.ds-menu-item:hover { background: #252733; }

.ds-menu-item-selected { display: flex; flex-direction: column; background: #7aa2f7; color: #1a1b26; font: 400 1em/1 monospace; padding: 0 1ch; list-style: none; }
.ds-menu-item-selected__name { padding-left: 3ch; font-weight: 400; }
.ds-menu-item-selected__desc { color: #1a1b26; padding-left: 3ch; }

.ds-pane { position: relative; box-sizing: border-box; background: #20222e; border: 1px solid #ffffff; padding: 1ch; font: 400 1em/1 monospace; color: #c0caf5; }
.ds-pane__title { position: absolute; top: -0.6em; left: 2ch; margin: 0; padding: 0 1ch; background: #20222e; color: #7aa2f7; font: inherit; text-transform: lowercase; }
.ds-pane--danger .ds-pane__title { color: #f7768e; }
.ds-pane__body { overflow: hidden; }

.ds-step-row { display: flex; gap: 1ch; font: 400 1em/1 monospace; white-space: nowrap; overflow: hidden; list-style: none; }
.ds-step-row--pending { color: #565f89; }
.ds-step-row--running { color: #7aa2f7; }
.ds-step-row--done { color: #9ece6a; }
.ds-step-row--failed { color: #f7768e; }
.ds-step-row--skipped { color: #e0af68; }
.ds-step-row__note { margin-left: auto; color: inherit; }

.ds-confirm__actions { display: flex; flex-direction: column; gap: 1ch; margin-top: 1ch; }
.ds-confirm__action { text-align: left; background: #20222e; color: #c0caf5; border: 0; font: 400 1em/1 monospace; padding: 0 1ch; }
.ds-confirm__action--focused { background: #7aa2f7; color: #1a1b26; }
.ds-confirm__action:hover { background: #252733; }
.ds-confirm__action--focused:hover { background: #7aa2f7; }
